import pathlib,json,datetime
p=pathlib.Path('/home/appontrack/.ontrack-saas/voice-lab/diagnostics')
rows=[]
if p.exists():
 for f in sorted(p.glob('owner-1-*.jsonl'))[-3:]:
  if f.is_file() and not f.is_symlink():
   for line in f.read_text().splitlines()[-400:]:
    try:
     obj=json.loads(line);stage=obj.get('stage','')
     if stage in ('fish_request_start','fish_http_response','fish_first_audio','fish_complete','turn_complete','token_http_success','token_upstream_error','fish_first_byte'):
      rows.append({'stage':stage,'elapsed_ms':obj.get('meta',{}).get('elapsed_ms'),'http_status':obj.get('meta',{}).get('http_status')})
    except Exception:pass
print(json.dumps({'events':rows[-70:],'count':len(rows)},separators=(',',':')))
